"""Prepare Thunderbird for the RN-2041 correspondence episode.

This episode answers messages that are already in the account's Inbox and sends
the replies through a capture mailbox on the guest loopback.  Preparation
launches Thunderbird and confirms the profile carries the seeded Inbox with the
expected message count and the six source subjects, that Sent and Drafts are
still empty, that the test identity appears in the profile, and that the capture
mailbox the replies are posted to is listening.  It sends nothing.
"""

from __future__ import annotations

import json
from typing import Any, Mapping

from evaluators.cua_review.core.initialization import InitializationError, MacAppInitializer

#: Thunderbird's profile directory, relative to the guest home directory.
DEFAULT_PROFILE_ROOT = "~/Library/Thunderbird/Profiles"

#: Where the capture mailbox keeps the messages it receives.
DEFAULT_SMTP_CAPTURE_DIR = "~/Library/Application Support/ThunderbirdBench/fake_smtp"

#: The capture mailbox's default loopback port.
DEFAULT_SMTP_PORT = 1025


class ThunderbirdRN2041SnapshotInitializer(MacAppInitializer):
    """Confirm the Thunderbird correspondence starting point an episode assumes."""

    INITIALIZER_ID = (
        "initializers.macos.thunderbird_rn2041_snapshot:ThunderbirdRN2041SnapshotInitializer"
    )
    APP_NAME = "Thunderbird"
    BUNDLE_ID = "org.mozilla.thunderbird"
    SETTLE_MS = 7000

    def verify_preconditions(self, controller: Any, params: Mapping[str, Any]) -> str:
        profile_root = str(params.get("profile_root") or DEFAULT_PROFILE_ROOT)
        script = "\n".join(
            [
                "import json",
                "from pathlib import Path",
                "",
                f"root = Path({profile_root!r}).expanduser()",
                "def mbox_count(path):",
                "    if path is None or not path.is_file():",
                "        return 0",
                "    with path.open('rb') as handle:",
                "        return sum(1 for line in handle if line.startswith(b'From '))",
                "profiles = []",
                "if root.is_dir():",
                "    for profile in sorted(root.iterdir()):",
                "        if not profile.is_dir():",
                "            continue",
                "        boxes = {}",
                "        for top in ('Mail', 'ImapMail'):",
                "            base = profile / top",
                "            if not base.is_dir():",
                "                continue",
                "            for candidate in base.rglob('*'):",
                "                if candidate.is_file() and candidate.suffix not in ('.msf', '.dat'):",
                "                    boxes.setdefault(candidate.name, str(candidate))",
                "        profiles.append({'name': profile.name, 'boxes': boxes})",
                "print(json.dumps({'root': str(root), 'profiles': profiles}))",
            ]
        )
        evidence = self._guest_json(controller, script, what="the Thunderbird mail store")
        profiles = [item for item in (evidence.get("profiles") or []) if item.get("boxes")]
        if not profiles:
            raise InitializationError(
                f"Thunderbird has no mail store under {evidence.get('root')}"
            )
        profile = profiles[0]
        boxes = dict(profile.get("boxes") or {})

        def count(name: str) -> int:
            path = boxes.get(str(params.get(name + "_mailbox") or name))
            return mbox_count(controller, path)

        def mbox_count(controller: Any, path: Any) -> int:
            if not path:
                return 0
            observed = self._guest_json(
                controller,
                "\n".join(
                    [
                        "import json",
                        "from pathlib import Path",
                        f"path = Path({str(path)!r})",
                        "total = 0",
                        "if path.is_file():",
                        "    with path.open('rb') as handle:",
                        "        total = sum(1 for line in handle if line.startswith(b'From '))",
                        "print(json.dumps(total))",
                    ]
                ),
                what="a Thunderbird mailbox",
            )
            return int(observed or 0)

        expected_count = int(params.get("source_message_count") or 0)
        source_count = count("source")
        if expected_count and source_count != expected_count:
            raise InitializationError(
                f"the {params.get('source_mailbox')} mailbox carries {source_count} messages, "
                f"expected {expected_count}"
            )

        inbox_path = boxes.get(str(params.get("source_mailbox") or "Inbox"))
        subjects = [str(subject) for subject in (params.get("source_subjects") or [])]
        if subjects:
            observed = self._guest_json(
                controller,
                "\n".join(
                    [
                        "import json",
                        "from pathlib import Path",
                        f"path = Path({str(inbox_path)!r})" if inbox_path else "path = None",
                        f"subjects = {json.dumps(subjects)}",
                        "body = path.read_bytes() if path is not None and path.is_file() else b''",
                        "found = [s for s in subjects if ('Subject: ' + s).encode('utf-8') in body]",
                        "print(json.dumps({'found': found, 'total': len(subjects)}))",
                    ]
                ),
                what="the Thunderbird source subjects",
            )
            missing = [subject for subject in subjects if subject not in set(observed.get("found") or [])]
            if missing:
                raise InitializationError(
                    "the Inbox does not carry the seeded subject(s) "
                    + ", ".join(repr(subject) for subject in missing)
                )

        for role in ("sent", "drafts"):
            mailbox = str(params.get(role + "_mailbox") or role.title())
            if count(role) > 0:
                raise InitializationError(
                    f"the {mailbox} mailbox is not empty before the task ran"
                )

        identity = str(params.get("identity_email") or "")
        if identity:
            found_identity = self._guest_json(
                controller,
                "\n".join(
                    [
                        "import json",
                        "from pathlib import Path",
                        f"root = Path({profile_root!r}).expanduser()",
                        f"needle = {identity!r}.encode('utf-8')",
                        "hits = 0",
                        "for path in root.rglob('*'):",
                        "    if path.is_file() and path.suffix not in ('.sqlite', '.db'):",
                        "        try:",
                        "            if needle in path.read_bytes():",
                        "                hits += 1",
                        "        except OSError:",
                        "            pass",
                        "print(json.dumps(hits))",
                    ]
                ),
                what="the Thunderbird identity",
            )
            if not int(found_identity or 0):
                raise InitializationError(
                    f"the Thunderbird profile carries no {identity} identity"
                )

        self._verify_capture_mailbox(controller, params)

        return (
            f"Thunderbird is running with {source_count} Inbox messages, the six seeded "
            f"subjects, empty {params.get('sent_mailbox')} and {params.get('drafts_mailbox')}, "
            f"and the capture mailbox listening"
        )

    def _verify_capture_mailbox(self, controller: Any, params: Mapping[str, Any]) -> None:
        host = str(params.get("smtp_host") or "127.0.0.1")
        port = int(params.get("smtp_port") or DEFAULT_SMTP_PORT)
        capture_dir = str(params.get("smtp_capture_dir") or DEFAULT_SMTP_CAPTURE_DIR)
        script = "\n".join(
            [
                "import json",
                "import socket",
                "from pathlib import Path",
                f"host, port = {host!r}, {port}",
                "sock = socket.socket()",
                "sock.settimeout(5)",
                "try:",
                "    sock.connect((host, port))",
                "    listening = True",
                "except Exception:",
                "    listening = False",
                "finally:",
                "    sock.close()",
                f"capture = Path({capture_dir!r}).expanduser()",
                "print(json.dumps({'listening': listening, 'capture_dir': str(capture), 'capture_exists': capture.is_dir()}))",
            ]
        )
        observed = self._guest_json(controller, script, what="the capture mailbox")
        if not observed.get("listening"):
            raise InitializationError(
                f"the capture mailbox is not listening on {host}:{port}"
            )
        if not observed.get("capture_exists"):
            raise InitializationError(
                f"the capture directory is missing at {observed.get('capture_dir')}"
            )
